INSERT INTO `mod_forever_journal_lore` (`ID`, `Zone`, `Kind`, `SortOrder`, `Faction`, `Races`, `Classes`, `Era`, `Title`, `Body`, `Sources`) VALUES
(1583000, 1583, 0, 1, 0, 0, 0, 0, 'Blackrock Spire', 'The fortress carved into the upper levels of Blackrock Mountain, designed by the master mason Franclorn Forgewright as the symbol of Dark Iron power. In the First War it sheltered Gul''dan''s Shadow Council; in the Second it was the Horde''s headquarters, where Orgrim Doomhammer made his war plans.\n\nNow Nefarian, son of Deathwing, holds it. His dragonspawn and the Dark Horde of Rend Blackhand fill its halls, its lower city is crowded with orcs, trolls and ogres, and from its heights Nefarian wages war on the Dark Irons below and carries on his sinister experiments.', 'warcraft.wiki.gg: Blackrock Spire (History); warcraft.wiki.gg: Blackrock Mountain'),
(1583001, 1583, 1, 1, 0, 0, 0, 0, 'Hordemar City', 'The lower city of the Spire, a sprawl of ogre and orc quarters. The Spirestone ogres hold Mok''Doom under their highlord, though he is only a figurehead for their true master.', 'warcraft.wiki.gg: Highlord Omokk; warcraft.wiki.gg: Urok Doomhowl'),
(1583002, 1583, 1, 2, 0, 0, 0, 0, 'Tazz''Alor and the Skitterweb Tunnels', 'Forest trolls of the Smolderthorn tribe hold Tazz''Alor, led by a shadow hunter and a war master. Beyond them, crystal spiders nest in the tunnels around their great broodmother.', 'warcraft.wiki.gg: Shadow Hunter Vosh''gajin; warcraft.wiki.gg: War Master Voone; warcraft.wiki.gg: Mother Smolderweb'),
(1583003, 1583, 1, 3, 0, 0, 0, 0, 'Halycon''s Nest and the Lower Citadel', 'Deep in the lower spire, the Bloodaxe Legion keeps the great worgs that breed their attack wolves, and Overlord Wyrmthalak, taskmaster of the lower citadel, takes his orders from General Drakkisath above.', 'warcraft.wiki.gg: Halycon; warcraft.wiki.gg: Overlord Wyrmthalak'),
(1583004, 1583, 1, 4, 0, 0, 0, 0, 'The Hall of Binding', 'The gate to the upper spire, where warlocks of the Blackhand keep a powerful fire elemental, Pyroguard Emberseer, chained in a trance, draining his power to hasten the hatching of black dragon eggs.', 'warcraft.wiki.gg: Pyroguard Emberseer; warcraft.wiki.gg: Blackrock Mountain (After the Great Wars)'),
(1583005, 1583, 1, 5, 0, 0, 0, 0, 'The Rookery', 'A hall of black dragon eggs, guarded by elite dragonkin, warmed by a great crystal called the Father Flame.', 'warcraft.wiki.gg: Solakar Flamewreath'),
(1583006, 1583, 1, 6, 0, 0, 0, 0, 'The Stadium', 'Where Lord Victor Nefarius, in his mortal guise, sets beasts and soldiers against intruders for his amusement, before Warchief Rend Blackhand rides down on his drake to finish them.', 'warcraft.wiki.gg: Rend Blackhand; warcraft.wiki.gg: Gyth'),
(1583007, 1583, 1, 7, 0, 0, 0, 0, 'The Furnace and the Halls of Ascension', 'The Furnace holds a captured core hound of Ragnaros, tortured and retrained to guard the spire. Beyond, past the Halls of Ascension, General Drakkisath rules from his throne room at the summit, commanding the war to drive the Dark Irons from the mountain.', 'warcraft.wiki.gg: The Beast; warcraft.wiki.gg: General Drakkisath'),
(1583030, 1583, 2, 1, 0, 0, 0, 0, 'Highlord Omokk', 'The apparent leader of the Spirestone ogres, in truth a front for their real master, Urok Doomhowl.', 'warcraft.wiki.gg: Highlord Omokk'),
(1583031, 1583, 2, 2, 0, 0, 0, 0, 'Urok Doomhowl', 'The true master of the Spirestone ogres, who cursed the troll Warosh and stole his mojo.', 'warcraft.wiki.gg: Urok Doomhowl'),
(1583032, 1583, 2, 3, 0, 0, 0, 0, 'Shadow Hunter Vosh''gajin', 'A forest troll shadow hunter of Tazz''Alor, the former lover of a troll blacksmith in Everlook. She gave him the scar on his face, and called it a love tap.', 'warcraft.wiki.gg: Shadow Hunter Vosh''gajin'),
(1583033, 1583, 2, 4, 0, 0, 0, 0, 'War Master Voone', 'The forest troll war master of Tazz''Alor, who leads the Smolderthorn in battle.', 'warcraft.wiki.gg: War Master Voone'),
(1583034, 1583, 2, 5, 0, 0, 0, 0, 'Mother Smolderweb', 'The great broodmother of the crystal spiders that nest in the tunnels of the lower spire.', 'warcraft.wiki.gg: Mother Smolderweb'),
(1583035, 1583, 2, 6, 0, 0, 0, 0, 'Halycon and Gizrul', 'A giant red-and-black worg of the Bloodaxe Legion and her mate, Gizrul the Slavener, who sire the orcs'' attack worgs, whatever the rumours of demonic origins. She is kept with her pups in her nest, heavily guarded.', 'warcraft.wiki.gg: Halycon'),
(1583036, 1583, 2, 7, 0, 0, 0, 0, 'Overlord Wyrmthalak', 'The overlord and taskmaster of the lower city, who takes his commands from General Drakkisath.', 'warcraft.wiki.gg: Overlord Wyrmthalak'),
(1583037, 1583, 2, 8, 0, 0, 0, 0, 'Pyroguard Emberseer', 'A powerful fire elemental held captive by the Blackhand Incarcerators. Should the warlocks'' trance break, he breaks free, and tries to destroy everything near him.', 'warcraft.wiki.gg: Pyroguard Emberseer'),
(1583038, 1583, 2, 9, 0, 0, 0, 0, 'Solakar Flamewreath', 'A dragonspawn who comes to defend the Rookery''s eggs when anyone touches the Father Flame.', 'warcraft.wiki.gg: Solakar Flamewreath'),
(1583039, 1583, 2, 10, 0, 0, 0, 0, 'Warchief Rend Blackhand', 'Dal''rend, the bloodthirsty son of Blackhand the Destroyer and warchief of the Dark Horde, who believes he is the rightful warchief of the Horde by birth and means to overthrow Thrall. He has allied the Dark Horde with Nefarian, and together they breed the chromatic dragonflight. He rides the chromatic drake Gyth.', 'warcraft.wiki.gg: Rend Blackhand; warcraft.wiki.gg: Gyth'),
(1583040, 1583, 2, 11, 0, 0, 0, 0, 'The Beast', 'A core hound of Ragnaros captured by Nefarian''s forces, tortured for their amusement and retrained to guard the spire. It once swallowed a gnome named Pip Quickwit whole; his lava-proof suit kept him alive in its belly for weeks.', 'warcraft.wiki.gg: The Beast'),
(1583041, 1583, 2, 12, 0, 0, 0, 0, 'General Drakkisath', 'The black dragonspawn who rules Nefarian''s armies, overseeing from the pinnacle of the spire their war to drive the Dark Irons out of the mountain. He bears the Blackblade of Shahram.', 'warcraft.wiki.gg: General Drakkisath'),
(1583042, 1583, 2, 13, 0, 0, 0, 0, 'Lord Victor Nefarius', 'The Lord of Blackrock, a nobleman in appearance, whom the Dark Horde serves. He is Nefarian, son of Deathwing, and from the Spire''s highest reaches he breeds new dragons of every colour to make an army that can conquer Azeroth.', 'warcraft.wiki.gg: Blackrock Mountain; warcraft.wiki.gg: Rend Blackhand');
